"use client";

import { useEffect, useMemo, useState } from "react";
import { StickyNote, Send, X, Check, Eye } from "lucide-react";
import { toast } from "react-toastify";

import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useAuth } from "@/lib/auth-context";
import { hasRole } from "@/lib/role-utils";

interface VisitNoteItem {
  id?: string;
  content?: string | null;
  noteType?: string | null;
  createdBy?: {
    id?: string;
    firstName?: string;
    lastName?: string;
  };
  createdAt?: string;
  viewed?: boolean;
}

interface VisitNotesFloatingProps {
  notes: VisitNoteItem[];
  noteTypes: string[];
  title?: string;
  allowedDisplayTypes?: string[];
  onAddNote?: (noteType: string, content: string) => Promise<void>;
  onMarkAsViewed?: (noteId: string) => Promise<void>;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  hideToggleButton?: boolean;
  visitId?: string;
  visitDepartmentId?: string;
}

export default function VisitNotesFloating({
  notes,
  noteTypes,
  title = "Visit Notes",
  allowedDisplayTypes,
  onAddNote,
  onMarkAsViewed,
  open,
  onOpenChange,
  hideToggleButton = false,
}: VisitNotesFloatingProps) {
  const [internalOpen, setInternalOpen] = useState(false);
  const { doctor } = useAuth();
  const controlled = typeof open === "boolean";
  const isOpen = controlled ? open : internalOpen;
  const setOpenState = (value: boolean) => {
    if (controlled) {
      onOpenChange?.(value);
    } else {
      setInternalOpen(value);
    }
  };
  const [text, setText] = useState("");
  const [selectedType, setSelectedType] = useState(noteTypes[0] || "PUBLIC");
  const [submitting, setSubmitting] = useState(false);
  // In-flight "mark as read" request — disables the mark-all button and note
  // clicks so duplicate markNotesViewed mutations can't fire.
  const [markingRead, setMarkingRead] = useState(false);

  useEffect(() => {
    if (!noteTypes.includes(selectedType)) {
      setSelectedType(noteTypes[0] || "PUBLIC");
    }
  }, [noteTypes, selectedType]);

  const userRoles = doctor?.roles || [];
  const isManagerOrAdmin =
    hasRole(userRoles, "MANAGER") || hasRole(userRoles, "ADMIN");

  const visibleNotes = useMemo(() => {
    if (isManagerOrAdmin) {
      return notes || [];
    }
    if (!allowedDisplayTypes || allowedDisplayTypes.length === 0) {
      return notes || [];
    }

    const allowed = new Set(allowedDisplayTypes);
    return (notes || []).filter(
      (note) => note?.noteType && allowed.has(String(note.noteType)),
    );
  }, [allowedDisplayTypes, notes, isManagerOrAdmin]);

  const unreadNotesCount = useMemo(
    () => (visibleNotes || []).filter((note) => !note?.viewed).length,
    [visibleNotes],
  );

  const handleAdd = async () => {
    if (!onAddNote) return;
    const trimmed = text.trim();
    if (!trimmed) return;

    setSubmitting(true);
    try {
      await onAddNote(selectedType, trimmed);
      setText("");
    } catch (error: any) {
      const message = error?.message || "Failed to save note";
      toast.error(message);
      console.error("Failed to add note", error);
    } finally {
      setSubmitting(false);
    }
  };

  const handleClear = () => {
    setText("");
  };

  const hasDraft = text.trim().length > 0;

  const handleMarkAsViewed = async (noteId: string) => {
    if (!onMarkAsViewed || markingRead) return;
    setMarkingRead(true);
    try {
      await onMarkAsViewed(noteId);
    } catch (error: any) {
      console.error("Failed to mark note as viewed", error);
    } finally {
      setMarkingRead(false);
    }
  };

  const markAllAsRead = async () => {
    if (!onMarkAsViewed || markingRead) return;
    const unread = (visibleNotes || []).filter(
      (note) => !note?.viewed && note?.id,
    );
    if (unread.length === 0) return;

    setMarkingRead(true);
    try {
      await Promise.all(unread.map((note) => onMarkAsViewed(String(note.id))));
    } catch (error: any) {
      console.error("Failed to mark notes as viewed", error);
    } finally {
      setMarkingRead(false);
    }
  };

  const addBulletPrefix = () => {
    setText((prev) => (prev ? `${prev}\n- ` : "- "));
  };

  const addNumberPrefix = () => {
    setText((prev) => {
      if (!prev) return "1. ";
      const lines = prev.split("\n");
      const last = lines[lines.length - 1] || "";
      const match = last.match(/^(\d+)\.\s/);
      const next = match ? Number(match[1]) + 1 : 1;
      return `${prev}\n${next}. `;
    });
  };

  const formatLineBlocks = (content: string) => {
    const lines = content.split("\n");
    const blocks: Array<{ type: "ul" | "ol" | "p"; items: string[] }> = [];

    const pushBlock = (type: "ul" | "ol" | "p", value: string) => {
      const last = blocks[blocks.length - 1];
      if (last && last.type === type) {
        last.items.push(value);
        return;
      }
      blocks.push({ type, items: [value] });
    };

    lines.forEach((rawLine) => {
      const line = rawLine.trimEnd();
      if (!line.trim()) return;

      if (line.startsWith("- ")) {
        pushBlock("ul", line.slice(2));
        return;
      }

      const numbered = line.match(/^\d+\.\s+(.*)$/);
      if (numbered) {
        pushBlock("ol", numbered[1]);
        return;
      }

      pushBlock("p", line);
    });

    if (blocks.length === 0) {
      return <p className="text-xs text-muted-foreground">No content</p>;
    }

    return (
      <div className="space-y-1">
        {blocks.map((block, idx) => {
          if (block.type === "ul") {
            return (
              <ul
                key={`ul-${idx}`}
                className="list-disc pl-4 text-xs text-foreground space-y-0.5"
              >
                {block.items.map((item, itemIdx) => (
                  <li key={`ul-${idx}-${itemIdx}`}>{item}</li>
                ))}
              </ul>
            );
          }

          if (block.type === "ol") {
            return (
              <ol
                key={`ol-${idx}`}
                className="list-decimal pl-4 text-xs text-foreground space-y-0.5"
              >
                {block.items.map((item, itemIdx) => (
                  <li key={`ol-${idx}-${itemIdx}`}>{item}</li>
                ))}
              </ol>
            );
          }

          return block.items.map((item, itemIdx) => (
            <p
              key={`p-${idx}-${itemIdx}`}
              className="text-xs text-foreground whitespace-pre-wrap"
            >
              {item}
            </p>
          ));
        })}
      </div>
    );
  };

  return (
    <>
      {!hideToggleButton && (
        <div className="fixed right-6 top-1/2 -translate-y-1/2 z-40">
          <Button
            type="button"
            size="icon"
            className="relative rounded-full h-12 w-12 border-2 border-white bg-card text-foreground hover:bg-card shadow-lg"
            onClick={() => setOpenState(!isOpen)}
            aria-label="Toggle notes"
            title="Notes"
          >
            <StickyNote className="h-5 w-5" />
            {!isOpen && unreadNotesCount > 0 && (
              <span className="absolute -top-1.5 -right-1.5 min-w-5 h-5 px-1 rounded-full bg-primary text-primary-foreground text-[12px] font-bold leading-5 text-center shadow-lg ring-2 ring-background animate-bounce">
                {unreadNotesCount}
              </span>
            )}
          </Button>
        </div>
      )}

      {isOpen && (
        <div className="fixed right-20 top-1/2 -translate-y-1/2 w-90 max-w-[calc(100vw-7rem)] z-40 bg-background border border-border rounded-2xl shadow-2xl p-4 space-y-4">
          <div>
            <h3 className="text-sm font-semibold text-foreground">{title}</h3>
            <p className="text-xs text-muted-foreground">View and add notes</p>
          </div>

          <div className="max-h-56 overflow-y-auto rounded-xl border border-border bg-card p-3 space-y-2">
            {visibleNotes.length === 0 ? (
              <p className="text-xs text-muted-foreground">No notes yet.</p>
            ) : (
              visibleNotes.map((note, idx) => (
                <div
                  key={`${note.id || note.noteType || "note"}-${idx}`}
                  className="rounded-lg border border-border bg-card p-2"
                  onClick={() =>
                    !note.viewed && note.id && !markingRead
                      ? handleMarkAsViewed(note.id)
                      : undefined
                  }
                >
                  <div className="flex items-center justify-between gap-2">
                    <p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                      {note.noteType || "PUBLIC"}
                      {!note.viewed && (
                        <span className="ml-1 text-[10px] bg-primary text-primary-foreground px-1 rounded-full animate-pulse">
                          NEW
                        </span>
                      )}
                    </p>

                    {(() => {
                      const createdBy = note.createdBy;
                      if (!createdBy)
                        return (
                          <span className="text-[11px] text-muted-foreground">
                            Unknown
                          </span>
                        );

                      if (doctor && createdBy.id === doctor.id) {
                        return (
                          <span className="text-[11px] text-muted-foreground italic">
                            You
                          </span>
                        );
                      }
                      const hasFirst = !!createdBy.firstName?.trim();
                      const hasLast = !!createdBy.lastName?.trim();

                      if (hasFirst && !hasLast) return null;
                      const fullName = [
                        createdBy.firstName?.trim(),
                        createdBy.lastName?.trim(),
                      ]
                        .filter(Boolean)
                        .join(" ");
                      return fullName ? (
                        <span className="text-[11px] text-muted-foreground">
                          {fullName}
                        </span>
                      ) : null;
                    })()}
                  </div>
                  {formatLineBlocks(note.content || "")}
                </div>
              ))
            )}
          </div>

          {onAddNote && (
            <div className="space-y-2">
              <div className="flex items-center gap-2 flex-wrap">
                <Button
                  type="button"
                  variant="outline"
                  className="h-7 rounded-full px-3 text-[12px]"
                  onClick={addBulletPrefix}
                >
                  • List
                </Button>
                <Button
                  type="button"
                  variant="outline"
                  className="h-7 rounded-full px-3 text-[12px]"
                  onClick={addNumberPrefix}
                >
                  1. Numbered
                </Button>

                {noteTypes.length > 1 ? (
                  <Select value={selectedType} onValueChange={setSelectedType}>
                    <SelectTrigger className="h-7 min-h-0 w-auto rounded-full border-border bg-muted px-3 py-0 text-[12px] font-semibold text-foreground leading-none [&>svg]:hidden">
                      <SelectValue placeholder="Type" />
                    </SelectTrigger>
                    <SelectContent className="min-w-30 rounded-xl p-1">
                      {noteTypes.map((type) => (
                        <SelectItem
                          key={type}
                          value={type}
                          className="h-7 text-[12px] leading-none px-2"
                        >
                          {type}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <div className="inline-flex rounded-full border border-border/70 px-3 py-1 text-[12px] font-semibold text-muted-foreground">
                    {selectedType}
                  </div>
                )}
              </div>

              <Textarea
                value={text}
                onChange={(e) => setText(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key !== "Enter" || e.shiftKey) return;

                  const textarea = e.currentTarget;
                  const cursorPos = textarea.selectionStart;
                  const textBeforeCursor = text.slice(0, cursorPos);
                  const lines = textBeforeCursor.split("\n");
                  const currentLine = lines[lines.length - 1] || "";

                  const bulletMatch = currentLine.match(/^(\s*)-\s/);
                  if (bulletMatch) {
                    e.preventDefault();
                    const indent = bulletMatch[1];
                    const textAfterCursor = text.slice(cursorPos);
                    const updated = `${textBeforeCursor}\n${indent}- ${textAfterCursor}`;
                    setText(updated);
                    setTimeout(() => {
                      textarea.selectionStart = textarea.selectionEnd =
                        cursorPos + indent.length + 3;
                    }, 0);
                    return;
                  }

                  const numberedMatch = currentLine.match(/^(\s*)(\d+)\.\s/);
                  if (numberedMatch) {
                    e.preventDefault();
                    const indent = numberedMatch[1];
                    const nextNum = Number(numberedMatch[2]) + 1;
                    const textAfterCursor = text.slice(cursorPos);
                    const updated = `${textBeforeCursor}\n${indent}${nextNum}. ${textAfterCursor}`;
                    setText(updated);
                    setTimeout(() => {
                      textarea.selectionStart = textarea.selectionEnd =
                        cursorPos + indent.length + String(nextNum).length + 3;
                    }, 0);
                  }
                }}
                rows={5}
                placeholder="Write note..."
                className="bg-muted border-border"
              />

              <div className="flex items-center justify-end gap-2">
                {/* Mark read (always visible if handler provided) */}
                {onMarkAsViewed && (
                  <Button
                    type="button"
                    variant="outline"
                    size="icon"
                    className="h-9 w-9 rounded-full"
                    onClick={markAllAsRead}
                    disabled={unreadNotesCount === 0 || markingRead}
                    aria-label="Mark all as read"
                    title="Mark all as read"
                  >
                    <Eye className="h-4 w-4" />
                  </Button>
                )}

                {/* Draft actions: show only when textarea has content */}
                {hasDraft && (
                  <>
                    <Button
                      type="button"
                      variant="outline"
                      size="icon"
                      className="h-9 w-9 rounded-full"
                      onClick={handleClear}
                      aria-label="Clear"
                      title="Clear"
                    >
                      <X className="h-4 w-4" />
                    </Button>
                    <Button
                      type="button"
                      size="icon"
                      className="h-9 w-9 rounded-full"
                      onClick={handleAdd}
                      disabled={submitting}
                      aria-label="Send note"
                      title="Send note"
                    >
                      {submitting ? (
                        <Check className="h-4 w-4 opacity-60" />
                      ) : (
                        <Send className="h-4 w-4" />
                      )}
                    </Button>
                  </>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </>
  );
}
