"use client";

import { useState } from "react";
import type { Dispatch, SetStateAction, MutableRefObject } from "react";
import { toast } from "react-toastify";
import {
  applyInsuranceSelectionToItem,
  buildProductCoverageMaps,
  findBestMatchingCoverage,
  getItemInsuranceSplit,
  resolveBillingUnitPrice,
  type BillingData,
  type BillingItem,
  type BillingTotals,
  type CoverageTier,
} from "@/lib/billing-utils";
import { formatRWF } from "@/lib/utils";
import { getBasePatientSharePercentage } from "@/lib/api-types";
import {
  flattenVisitDepartmentsForBilling,
  getCoveragePercentageForBillingItem,
  isInsuranceActive,
} from "@/lib/visit-billing-mapper";
import {
  buildInvoiceHtml,
  openInvoicePreview,
  resolveInvoiceUrl,
  type InvoiceMutationResult,
} from "@/lib/invoice-utils";
import {
  buildCreateBillInput,
  buildEditBillInput,
} from "@/lib/billing-input-builders";
import type { Visit, VisitBilling, PatientInsurance } from "@/lib/api-types";
import type { VisitBillingTotals } from "@/lib/visit-billing-utils";
import type { VisitDepartment } from "@/hooks/types";
import type { ApiResponse } from "@/hooks/types";
import type {
  BillingPaymentMethod,
  CreateBillInput,
  EditBillInput,
} from "@/hooks/billing/hooks";

export interface BillingActionsContext {
  // Data
  visitId: string | null;
  visit: Visit | undefined;
  billingData: BillingData | null;
  existingVisitBilling: VisitBilling | null | undefined;
  existingBillingTotals: VisitBillingTotals | null;
  displayTotals: BillingTotals;
  /** Items included in the completion action: one department normally, the
   * complete visit when replacing a bill in edit mode. */
  selectedItems: BillingItem[];
  billingNotesByDepartment: Record<string, string>;
  editModeSnapshot: BillingItem[] | null;
  activeVisitInsurances: PatientInsurance[];
  activeVisitDepartment: VisitDepartment | null;
  topLevelBillingDepartments: VisitDepartment[];
  activeService?: string;
  canDischargeVisit: boolean;
  unreadBillingNotesCount: number;
  creatingBill: boolean;
  editingBill: boolean;
  isEditingBill: boolean;
  ENABLE_DISCHARGE: boolean;
  previewDepartmentId: string | null;
  doctor: { firstName?: string | null } | null;
  // Mutations
  createBill: (input: CreateBillInput) => Promise<ApiResponse<VisitBilling>>;
  editBill: (input: EditBillInput) => Promise<ApiResponse<VisitBilling>>;
  generateInvoice: (
    departmentInsuranceBillingId: string,
  ) => Promise<InvoiceMutationResult>;
  startBillEditing: (visitDepartmentId: string) => Promise<{ status: string; message?: string }>;
  completeBillEditing: (visitDepartmentId: string) => Promise<{ status: string; message?: string }>;
  cancelBillEditing: (visitDepartmentId: string, addedProductIds?: string[]) => Promise<{ status: string; message?: string }>;
  changeVisitDepartmentProfile: (
    visitDepartmentId: string,
    profileId?: string | null,
  ) => Promise<ApiResponse<any>>;
  updateDepartmentStatus: (
    visitDepartmentId: string,
    status: "ACTIVE" | "PENDING" | "COMPLETED",
  ) => Promise<ApiResponse<any>>;
  completeVisit: (visitId: string) => Promise<ApiResponse<any>>;
  linkVisitInsurances: (
    visitId: string,
    insuranceIds: string[],
  ) => Promise<ApiResponse<any>>;
  unlinkVisitInsurances: (
    visitId: string,
    insuranceIds: string[],
  ) => Promise<ApiResponse<any>>;
  addProduct: (
    visitId: string,
    departmentId: string,
    productId: string,
    quantity?: number,
    processorId?: string,
  ) => Promise<ApiResponse<any>>;
  // Refetches
  refetchVisit: () => Promise<unknown>;
  refetchBill: () => Promise<unknown>;
  // Setters
  setBillingData: Dispatch<SetStateAction<BillingData | null>>;
  setActiveVisitInsuranceIds: Dispatch<SetStateAction<string[]>>;
  setBillingRemapNonce: Dispatch<SetStateAction<number>>;
  setIsEditingBill: Dispatch<SetStateAction<boolean>>;
  setEditModeSnapshot: Dispatch<SetStateAction<BillingItem[] | null>>;
  setConfirmSheetMode: Dispatch<SetStateAction<"complete" | "edit">>;
  setBillJustCreated: Dispatch<SetStateAction<boolean>>;
  setPreviewOpen: Dispatch<SetStateAction<boolean>>;
  setPreviewDepartmentId: Dispatch<SetStateAction<string | null>>;
  setPreviewStartedAt: Dispatch<SetStateAction<number | null>>;
  setShowAddProductModal: Dispatch<SetStateAction<boolean>>;
  setAddingBillingItem: Dispatch<SetStateAction<boolean>>;
  setActiveService?: Dispatch<SetStateAction<string>>;
  hasLocalEditsRef?: MutableRefObject<boolean>;
}

/**
 * All async actions for BillingPageContent (bill creation/editing, discharge,
 * preview/print, insurance toggling, product adding). Extracted so the page
 * only composes state, derived values and the render tree.
 */
export function useBillingPageActions(ctx: BillingActionsContext) {
  const {
    visitId,
    visit,
    billingData,
    existingVisitBilling,
    existingBillingTotals,
    displayTotals,
    selectedItems,
    billingNotesByDepartment,
    editModeSnapshot,
    activeVisitInsurances,
    activeVisitDepartment,
    topLevelBillingDepartments,
    activeService,
    canDischargeVisit,
    unreadBillingNotesCount,
    creatingBill,
    editingBill,
    isEditingBill,
    ENABLE_DISCHARGE,
    previewDepartmentId,
    doctor,
    createBill,
    editBill,
    generateInvoice,
    startBillEditing,
    completeBillEditing,
    cancelBillEditing,
    changeVisitDepartmentProfile,
    updateDepartmentStatus,
    completeVisit,
    linkVisitInsurances,
    unlinkVisitInsurances,
    addProduct,
    refetchVisit,
    refetchBill,
    setBillingData,
    setActiveVisitInsuranceIds,
    setBillingRemapNonce,
    setIsEditingBill,
    setEditModeSnapshot,
    setConfirmSheetMode,
    setBillJustCreated,
    setPreviewOpen,
    setPreviewDepartmentId,
    setPreviewStartedAt,
    setShowAddProductModal,
    setAddingBillingItem,
    setActiveService,
    hasLocalEditsRef,
  } = ctx;

  const handleDownloadInvoice = async (
    departmentInsuranceBillingId: string,
    copyType?: string,
  ) => {
    if (unreadBillingNotesCount > 0) {
      toast.warn("Please read the unread notes before generating an invoice.");
      return;
    }
    const invoiceUrl = await resolveInvoiceUrl(
      departmentInsuranceBillingId,
      generateInvoice,
      copyType,
    );
    openInvoicePreview(invoiceUrl);
  };

  const handleChangeProfile = async (profileId: string | null) => {
    if (!activeVisitDepartment) return;
    try {
      const response = await changeVisitDepartmentProfile(
        activeVisitDepartment.id,
        profileId,
      );
      if (response?.status === "SUCCESS") {
        await refetchVisit();
        await refetchBill();
        // Force billingData to re-map so the new PROFILE products appear.
        setBillingRemapNonce((nonce) => nonce + 1);
        toast.success("Department profile updated");
      } else {
        toast.error(
          response?.message || "Failed to update the department profile",
        );
      }
    } catch (err) {
      console.error("Change profile error:", err);
      toast.error(
        err instanceof Error ? err.message : "Failed to update the profile",
      );
    }
  };

  const [dischargeConfirmOpen, setDischargeConfirmOpen] = useState(false);
  const [postBillingActionOpen, setPostBillingActionOpen] = useState(false);

  const requestDischarge = () => {
    if (!ENABLE_DISCHARGE) return;
    if (!visit) return;
    if (unreadBillingNotesCount > 0) {
      toast.warn("Please view the notes first before completing this visit.");
      return;
    }
    setDischargeConfirmOpen(true);
  };

  const handleDischargeVisit = async () => {
    if (!visit) return;

    try {
      const allDepartments = flattenVisitDepartmentsForBilling(
        visit.departments || [],
      );
      const notCompleted = allDepartments.filter(
        (dept) => dept.status !== "COMPLETED",
      );

      if (notCompleted.length > 0) {
        for (const dept of notCompleted) {
          const visitDeptId = String(dept.id || "");
          if (!visitDeptId) continue;

          const res = await updateDepartmentStatus(visitDeptId, "COMPLETED");
          if (res?.status !== "SUCCESS") {
            toast.error(
              res?.messages?.[0]?.text ||
                "Failed to complete department during discharge",
            );
            return;
          }
        }
      } else {
        // Re-apply completed status to last department to trigger backend visit completion aggregation.
        const fallbackDepartment = allDepartments[allDepartments.length - 1];
        const fallbackId = String(fallbackDepartment?.id || "");
        if (fallbackId) {
          await updateDepartmentStatus(fallbackId, "COMPLETED");
        }
      }

      await refetchVisit();
      await refetchBill();
      toast.success("Patient discharged successfully");
    } catch (err) {
      console.error("Discharge error:", err);
      toast.error("Failed to discharge patient");
    }
  };

  const handlePreviewBilling = async () => {
    if (!billingData) return;

    try {
      await refetchBill();
    } catch (err) {
      console.error("Failed to refresh bill before preview:", err);
      toast.warn(
        "Unable to refresh bill data before preview. Showing latest available bill.",
      );
    }

    const targetDept =
      (activeVisitDepartment
        ? topLevelBillingDepartments.find(
            (d) =>
              d.id === activeVisitDepartment.id ||
              (d.childVisitDepartments &&
                d.childVisitDepartments.some(
                  (c) => c.id === activeVisitDepartment.id,
                )),
          )
        : null) ||
      (previewDepartmentId
        ? topLevelBillingDepartments.find(
            (dept) => dept.id === previewDepartmentId,
          )
        : null) ||
      topLevelBillingDepartments[0];

    if (targetDept?.id) {
      setPreviewDepartmentId(targetDept.id);
    }

    setPreviewStartedAt(Date.now());
    setPreviewOpen(true);
  };

  const handleGenerateBill = async () => {
    if (!billingData || creatingBill || editingBill) return;

    if (unreadBillingNotesCount > 0) {
      toast.warn("Please view the notes first before completing the bill.");
      return;
    }

    // Match the API's edit-input limits before showing the confirmation flow.
    // Without this the user could prepare a valid-looking correction and only
    // learn about the limit after entering payment/note details.
    if (existingVisitBilling) {
      const rootId = (item: BillingItem) =>
        String(item.rootVisitDepartmentId || item.visitDepartmentId || "");
      const groups = new Map<string, BillingItem[]>();
      for (const item of billingData.items) {
        const id = rootId(item);
        groups.set(id, [...(groups.get(id) || []), item]);
      }
      const addedIds = new Set(
        billingData.items
          .filter((item) => !editModeSnapshot?.some((snapshot) => snapshot.id === item.id))
          .map((item) => item.id),
      );
      const addedByDepartment = new Map<string, number>();
      for (const item of billingData.items.filter((item) => addedIds.has(item.id))) {
        const id = rootId(item);
        addedByDepartment.set(id, (addedByDepartment.get(id) || 0) + 1);
      }
      if (groups.size > 20 || [...groups.values()].some((items) => items.length > 50) || [...addedByDepartment.values()].some((count) => count > 20)) {
        toast.error("This edit exceeds the billing limit (20 departments, 50 bill items, or 20 added items per department).");
        return;
      }
    }

    const unbilledItems = selectedItems.filter(
      (item) => item.paymentStatus !== "paid",
    );

    if (!isEditingBill && unbilledItems.length === 0) {
      if (canDischargeVisit && ENABLE_DISCHARGE) {
        requestDischarge();
        return;
      }
      toast.warn("All items in this department are already billed.");
      return;
    }

    // ── Pre-submission guards ───────────────────────────────────────────
    // Warn about items with zero price
    const zeroPriceItems = unbilledItems.filter(
      (item) => !item.price || item.price <= 0,
    );
    if (zeroPriceItems.length > 0) {
      const names = zeroPriceItems.map((i) => i.name).join(", ");
      toast.warn(`Items with no price will bill at 0: ${names}. Set a catalog price first.`);
    }

    // Warn about insurance selected but not covered
    const insuranceNotCovered = unbilledItems.filter(
      (item) => item.selectedInsuranceId && item.insuranceNotCovered,
    );
    if (insuranceNotCovered.length > 0) {
      const names = insuranceNotCovered.map((i) => i.name).join(", ");
      toast.warn(`Insurance not covering: ${names}. These will be billed as PRIVATE.`);
    }

    // Warn about items with quantity < 1 (shouldn't happen but guard anyway)
    const badQtyItems = unbilledItems.filter(
      (item) => !item.quantity || item.quantity < 1,
    );
    if (badQtyItems.length > 0) {
      const names = badQtyItems.map((i) => i.name).join(", ");
      toast.error(`Cannot bill items with invalid quantity: ${names}. Set quantity to at least 1.`);
      return;
    }

    // Pre-compute coverage for guards and bill building
    const coverageForItem = (item: BillingItem) =>
      getCoveragePercentageForBillingItem(item, activeVisitInsurances);

    // ── Edit-mode: warn if total changed significantly ──────────────────
    if (existingVisitBilling) {
      const correctedPatientPayable = billingData.items.reduce(
        (sum, item) => {
          const { patientAmount, skip } = getItemInsuranceSplit(
            item,
            coverageForItem(item),
          );
          return skip ? sum : sum + patientAmount;
        },
        0,
      );
      // Billing edits are FULLY INDEPENDENT snapshots — we never correlate the
      // corrected bill against previously-collected money, so there is no
      // "corrected bill less than paid / treated as credit" warning.
      // Warn if total changed significantly
      const originalTotal = billingData.items.reduce(
        (sum, item) => sum + item.price * item.quantity,
        0,
      );
      const diff = Math.abs(originalTotal - correctedPatientPayable);
      if (diff > 0.01 && diff / (originalTotal || 1) > 0.1) {
        toast.warn(
          `Bill total changed by ${formatRWF(diff)} (${Math.round((diff / (originalTotal || 1)) * 100)}%). Review before submitting.`,
        );
      }
    }

    try {

      const insuranceOpts = activeVisitInsurances.map((ins) => ({
        id: String(ins.id),
        providerId: String(ins.insuranceProvider.id),
        coverages: ins.insuranceProvider.coverages.map((c) => ({
          coverageId: String(c.id),
          departmentId: c.departmentId || null,
          departmentName: c.departmentName || null,
          encounterType: c.encounterType || null,
          patientSharePercentage: Number(c.patientSharePercentage ?? 0),
        })),
      }));
      let response: ApiResponse<VisitBilling>;
      if (existingVisitBilling) {
        // DEPARTMENT_EDITING: the department should already be in DEPARTMENT_EDITING
        // mode (set when the user clicked Edit). We just submit the edit and
        // the backend auto-restores the department status.
        response = await editBill(
          buildEditBillInput(
            billingData,
            editModeSnapshot ?? [],
            coverageForItem,
            insuranceOpts,
            existingVisitBilling?.version?.id,
            billingNotesByDepartment,
          ),
        );

        if (response.status !== "SUCCESS") {
          // Do not auto-cancel edit session on failure. Keep the user in edit
          // mode on the frontend and keep the backend DEPARTMENT_EDITING lock intact
          // so the user can correct validation errors or retry.
          toast.error(response.message || "Failed to update bill.");
          return;
        }
      } else {
        response = await createBill(
          buildCreateBillInput(
            billingData,
            unbilledItems,
            coverageForItem,
            insuranceOpts,
            billingNotesByDepartment,
          ),
        );
      }

      if (response.status === "SUCCESS") {
        setBillJustCreated(true);
        // Immediately exit edit mode and clear local edits guard
        setIsEditingBill(false);
        setEditModeSnapshot(null);
        setConfirmSheetMode("complete");
        if (hasLocalEditsRef) {
          hasLocalEditsRef.current = false;
        }

        const activeDept = visit?.departments?.find(
          (d) => (d.department?.name || "General") === activeService,
        );
        if (
          activeDept &&
          activeDept.status !== "COMPLETED" &&
          activeDept.status !== "DEPARTMENT_EDITING"
        ) {
          await updateDepartmentStatus(String(activeDept.id), "COMPLETED");
        }

        // Force a re-map of the updated billing data from server
        setBillingRemapNonce((n) => n + 1);

        // Refetch visit and bill data so the new version and items are loaded
        const freshVisitRes = await refetchVisit();
        await refetchBill();

        const freshVisitData = (freshVisitRes as any)?.data?.visit?.data;
        const updatedVisit: Visit | undefined = freshVisitData
          ? (freshVisitData as any)
          : visit;

        const allDepts = flattenVisitDepartmentsForBilling(
          updatedVisit?.departments || [],
        ).filter((d) => d.status !== "CANCELLED");

        const hasRemainingIncompleteDepts = allDepts.some(
          (d) => d.status !== "COMPLETED" && d.status !== "FINALISED",
        );

        const isLastDepartment =
          !hasRemainingIncompleteDepts &&
          updatedVisit?.status !== "COMPLETED" &&
          updatedVisit?.status !== "CANCELLED";

        if (isLastDepartment) {
          toast.success(
            existingVisitBilling
              ? "Bill updated successfully!"
              : "Department billed successfully!",
          );
          setPostBillingActionOpen(true);
        } else {
          await handlePreviewBilling();
          toast.success(
            existingVisitBilling
              ? "Bill updated successfully!"
              : "Department billed successfully!",
          );
        }
      } else {
        const errorMsg =
          response.messages?.map((m) => m.text).join(", ") ||
          (existingVisitBilling
            ? "Failed to update bill"
            : "Failed to create bill");
        toast.error(errorMsg);
      }
    } catch (err) {
      console.error(
        existingVisitBilling ? "Error updating bill:" : "Error creating bill:",
        err,
      );
      toast.error(
        existingVisitBilling
          ? "Failed to update bill. Please try again."
          : "Failed to create bill. Please try again.",
      );
    }
  };

  const handlePrintBillingInvoice = async () => {
    if (!billingData) return;

    if (existingVisitBilling) {
      if (unreadBillingNotesCount > 0) {
        toast.warn("Please read the unread notes before generating an invoice.");
        return;
      }
      const allDepts = existingVisitBilling.departments || [];
      const allIb = allDepts.flatMap((d) => d.insuranceBillings || []);
      if (allIb.length === 0) {
        toast.warn("No invoice available for this billing yet.");
        return;
      }

      // If only 1 private invoice exists (no insurance), generate and open directly
      const hasInsurance = allIb.some(
        (ib) => Boolean(ib.patientInsurance != null),
      );
      if (allIb.length === 1 && !hasInsurance && allIb[0].id) {
        try {
          const invoiceUrl = await resolveInvoiceUrl(
            allIb[0].id,
            generateInvoice,
            "PATIENT",
          );
          openInvoicePreview(invoiceUrl);
        } catch (err: unknown) {
          const message =
            err instanceof Error ? err.message : "Failed to generate invoice";
          toast.error(message);
        }
        return;
      }

      // Otherwise open the preview sheet where the user can choose the exact invoice copy
      await handlePreviewBilling();
      return;
    }

    const invoiceHtml = buildInvoiceHtml({
      invoiceNumber: billingData.visitId || "N/A",
      invoiceDate: billingData.updatedAt || new Date().toISOString(),
      patientName: billingData.patientName,
      patientId: billingData.patientId,
      paymentMethod: billingData.paymentMethod || "MOBILE_MONEY",
      visitDate: billingData.visitDate,
      items: billingData.items.map((item) => ({
        description: item.name,
        quantity: item.quantity,
        unitPrice: item.price,
        lineTotal: item.price * item.quantity,
      })),
      totals: {
        subtotal: existingBillingTotals?.totalAmount ?? displayTotals.subtotal,
        totalDue:
          existingBillingTotals?.totalAmount ?? displayTotals.totalAmount,
        paid:
          existingBillingTotals?.paidAmount ?? (billingData.amountPaid || 0),
        balance:
          existingBillingTotals?.outstandingAmount ??
          Math.max(0, displayTotals.totalAmount - (billingData.amountPaid || 0)),
      },
    });

    const printWindow = window.open("", "_blank", "width=900,height=1100");
    if (!printWindow) {
      toast.error(
        "Unable to open print window. Please allow pop-ups and try again.",
      );
      return;
    }

    printWindow.document.open();
    printWindow.document.write(invoiceHtml);
    printWindow.document.close();
    printWindow.focus();
    printWindow.print();
  };

  const handleAddInsuranceToVisit = async (insuranceId: string) => {
    if (!visitId) return;

    try {
      const response = await linkVisitInsurances(visitId, [insuranceId]);
      if (response?.status === "SUCCESS") {
        setActiveVisitInsuranceIds((current) =>
          current.includes(insuranceId) ? current : [...current, insuranceId],
        );
        // When an insurance is enabled on the visit, apply it to every unbilled
        // item that it actually covers. This makes "use insurance X for this
        // visit" propagate to the whole bill instead of leaving untouched items
        // on a different (default) insurance. Items the insurance does NOT cover
        // are left as-is (private / their current payer).
        const newlyLinked = (visit?.patient.patientInsurances || []).find(
          (ins) => String(ins.id) === String(insuranceId),
        );
        const providerId = newlyLinked?.insuranceProvider?.id
          ? String(newlyLinked.insuranceProvider.id)
          : undefined;
        if (providerId) {
          setBillingData((current) => {
            if (!current) return current;
            return {
              ...current,
              items: current.items.map((item) => {
                if (item.paymentStatus === "paid") return item;
                const covered = Boolean(
                  item.insuranceCoverageMeta?.[providerId]?.covered,
                );
                if (!covered) return item;
                return applyInsuranceSelectionToItem(
                  item,
                  insuranceId,
                  providerId,
                );
              }),
            };
          });
        }
        await refetchVisit();
        toast.success("Insurance enabled for this visit");
      } else {
        const errorMsg =
          response?.messages?.[0]?.text ||
          "Failed to enable insurance on visit";
        toast.error(errorMsg);
        await refetchVisit();
      }
    } catch (err) {
      console.error("Failed to link insurance to visit:", err);
      toast.error("Failed to enable insurance on visit. Please try again.");
      await refetchVisit();
    }
  };

  const handleRemoveInsuranceFromVisit = async (insuranceId: string) => {
    if (!visitId) return;

    // Frontend guard: check if any billed items use this insurance
    if (billingData) {
      const isUsedInBilledItem = billingData.items.some(
        (item) =>
          item.selectedInsuranceId === insuranceId &&
          (item.paymentStatus === "paid" || item.paymentStatus === "exempted"),
      );
      if (isUsedInBilledItem) {
        toast.error(
          "Cannot remove this insurance — it is already used in a billed item. " +
          "In edit mode, change or remove the products using this insurance first.",
        );
        return;
      }
    }

    try {
      const response = await unlinkVisitInsurances(visitId, [insuranceId]);
      if (response?.status === "SUCCESS") {
        setActiveVisitInsuranceIds((current) =>
          current.filter((id) => id !== insuranceId),
        );
        setBillingData((current) => {
          if (!current) return current;
          return {
            ...current,
            items: current.items.map((item) => {
              if (item.selectedInsuranceId !== insuranceId) return item;
              return applyInsuranceSelectionToItem(item, undefined, undefined);
            }),
          };
        });
        await refetchVisit();
        toast.success("Insurance removed from this visit");
      } else {
        const errorMsg =
          response?.messages?.[0]?.text ||
          "Failed to remove insurance from visit";
        toast.error(errorMsg);
        await refetchVisit();
      }
    } catch (err) {
      console.error("Failed to unlink insurance from visit:", err);
      toast.error("Failed to remove insurance from visit. Please try again.");
      await refetchVisit();
    }
  };

  const handleAddProduct = async (
    _type: "action" | "consumable",
    item: {
      id: string;
      name: string;
      clinicPrice?: number | null;
      privateRhicPrice?: number | null;
    },
    quantity: number,
    catalogDepartmentId: string,
    processorId?: string,
  ) => {
    if (!visit?.id) return;

    // In edit mode, skip the backend addVisitDepartmentProduct mutation — the
    // normal mutation is blocked on billed departments. Instead, construct a
    // local BillingItem and add it to the state. The actual backend add happens
    // atomically when the user submits via editBillVisit (addedProducts + billProducts).
    if (isEditingBill) {
      try {
        setAddingBillingItem(true);

        // Resolve the visit department that owns products for this catalog department
        const allDepts = (visit.departments || []) as Array<{
          id: string;
          department?: { id?: string; name?: string };
          products?: Array<{
            id: string;
            product?: {
              id?: string;
              name?: string;
              clinicPrice?: number | null;
              privateRhicPrice?: number | null;
            };
          }>;
        }>;
        const visitDept = allDepts.find(
          (d) => String(d.department?.id) === String(catalogDepartmentId),
        );

        // Try to get price from existing visit products (in case this product
        // was previously on the visit and is being re-added)
        let basePrice = Number(item.clinicPrice ?? item.privateRhicPrice ?? 0);
        if (basePrice === 0 && visitDept?.products) {
          const existingLine = visitDept.products.find(
            (p) => String(p.product?.id) === String(item.id),
          );
          if (existingLine?.product) {
            basePrice = Number(
              existingLine.product.clinicPrice ??
                existingLine.product.privateRhicPrice ??
                0,
            );
          }
        }

        const deptName = visitDept?.department?.name || "General";
        const tempId = `temp-${item.id}-${Date.now()}`;

        // Resolve processor name for display
        let processorName = "";
        if (processorId && visit?.departments) {
          for (const dept of visit.departments) {
            const proc = (dept.processors || []).find(
              (p) => String(p.id) === String(processorId),
            );
            if (proc) {
              processorName = [proc.firstName, proc.lastName]
                .filter(Boolean)
                .join(" ");
              break;
            }
          }
        }

        const rawCoverages = (item as any)?.insuranceCoverages || [];
        const { costs, meta } = buildProductCoverageMaps(
          rawCoverages.map((c: any) => ({
            insuranceProvider: c.insuranceProvider,
            cost: c.cost,
            covered: c.covered,
            notPaid: c.notPaid,
          }))
        );

        const activeLinkedInsurances = (visit.linkedInsurances || []).filter(isInsuranceActive);
        const coveringLinkedInsurance = activeLinkedInsurances.find((ins) => {
          const providerId = String(ins?.insuranceProvider?.id ?? "");
          if (!providerId) return false;
          const coverage = meta[providerId];
          const cost = costs[providerId];
          return coverage?.covered && typeof cost === "number" && Number.isFinite(cost) && cost > 0;
        });

        const defaultProviderId = coveringLinkedInsurance
          ? String(coveringLinkedInsurance.insuranceProvider.id)
          : undefined;
        const defaultVisitInsuranceId = coveringLinkedInsurance
          ? String(coveringLinkedInsurance.id)
          : undefined;

        const { price, notCovered } = resolveBillingUnitPrice(
          basePrice,
          costs,
          meta,
          defaultProviderId,
        );

        let selectedCoverageId: string | undefined = undefined;
        if (coveringLinkedInsurance) {
          const best = findBestMatchingCoverage(
            (coveringLinkedInsurance.insuranceProvider as any)?.coverages || [],
            catalogDepartmentId,
            undefined,
          );
          selectedCoverageId = best?.coverageId;
        }

        const newBillingItem: BillingItem = {
          id: tempId,
          productId: item.id,
          source: "USER",
          isNewInEditMode: true,
          name: item.name,
          quantity,
          price,
          basePrice,
          insuranceCoverageCosts: costs,
          insuranceCoverageMeta: meta,
          insuranceNotCovered: defaultVisitInsuranceId ? notCovered : false,
          type: "product",
          visitDepartmentId: visitDept?.id || catalogDepartmentId,
          rootVisitDepartmentId: visitDept?.id || catalogDepartmentId,
          departmentId: catalogDepartmentId,
          departmentName: deptName,
          departmentStatus: undefined,
          paymentStatus: "pending",
          exempted: false,
          exemptionType: "none",
          selectedInsuranceId: defaultVisitInsuranceId,
          selectedCoverageId,
          processorId: processorId || undefined,
          processorName: processorName || undefined,
          doneBy: {
            name: doctor?.firstName || "Doctor",
            title: "",
          },
        };

        setBillingData((prev) => {
          if (!prev) return prev;
          return {
            ...prev,
            items: [...prev.items, newBillingItem],
            updatedAt: new Date().toISOString(),
          };
        });

        setShowAddProductModal(false);
        const hasLinkedInsurances = (visit.linkedInsurances || []).length > 0;
        if (hasLinkedInsurances && !coveringLinkedInsurance) {
          toast.warn(`"${item.name}" is not covered (pays 0 RWF) by the patient's insurance. Added as Private (${basePrice.toLocaleString()} RWF).`);
        } else if (basePrice === 0 && price === 0) {
          toast.warn(`"${item.name}" has no price set — it will bill at 0. Set a catalog price first.`);
        } else {
          toast.success("Product added (will be saved when edit is submitted)");
        }
      } catch (err) {
        console.error("Failed to add product in edit mode:", err);
        toast.error("Failed to add product. Please try again.");
      } finally {
        setAddingBillingItem(false);
      }
      return;
    }

    // Normal (non-edit) mode: call the backend mutation directly
    try {
      setAddingBillingItem(true);
      const response = await addProduct(
        visit.id,
        catalogDepartmentId,
        item.id,
        quantity,
        processorId,
      );
      if (response?.status === "SUCCESS") {
        // Add the new product to billing data state directly instead of refetching
        if (billingData && response.data) {
          const newProduct = response.data;
          // The backend no longer returns a price on the visit product line —
          // derive the display price from the product catalog in the response.
          const addedLine = (
            (newProduct?.products || []) as Array<{
              id?: string;
              quantity?: number;
              product?: {
                id?: string;
                name?: string;
                clinicPrice?: number | null;
                privateRhicPrice?: number | null;
                insuranceCoverages?: any[];
              };
            }>
          ).find((p) => String(p.product?.id) === String(item.id));
          const catalogProduct = addedLine?.product;
          const basePrice = Number(
            catalogProduct?.clinicPrice ??
              catalogProduct?.privateRhicPrice ??
              0,
          );
          const departmentInfo = visit.departments?.find(
            (d) => d.id === newProduct?.id || d.id === catalogDepartmentId,
          );

          if (!addedLine?.id) {
            // Couldn't locate the newly added line in the response — refetch and
            // remap billing data from the server (with catalog prices) instead.
            await refetchVisit();
            setBillingRemapNonce((nonce) => nonce + 1);
          } else {
            // Resolve processor name for display
            let newProcessorName = "";
            if (processorId && visit?.departments) {
              for (const dept of visit.departments) {
                const proc = (dept.processors || []).find(
                  (p) => String(p.id) === String(processorId),
                );
                if (proc) {
                  newProcessorName = [proc.firstName, proc.lastName]
                    .filter(Boolean)
                    .join(" ");
                  break;
                }
              }
            }

            const rawCoverages = (catalogProduct as any)?.insuranceCoverages || (item as any)?.insuranceCoverages || [];
            const { costs, meta } = buildProductCoverageMaps(
              rawCoverages.map((c: any) => ({
                insuranceProvider: c.insuranceProvider,
                cost: c.cost,
                covered: c.covered,
                notPaid: c.notPaid,
              }))
            );

            const activeLinkedInsurances = (visit.linkedInsurances || []).filter(isInsuranceActive);
            const coveringLinkedInsurance = activeLinkedInsurances.find((ins) => {
              const providerId = String(ins?.insuranceProvider?.id ?? "");
              if (!providerId) return false;
              const coverage = meta[providerId];
              const cost = costs[providerId];
              return coverage?.covered && typeof cost === "number" && Number.isFinite(cost) && cost > 0;
            });

            const defaultProviderId = coveringLinkedInsurance
              ? String(coveringLinkedInsurance.insuranceProvider.id)
              : undefined;
            const defaultVisitInsuranceId = coveringLinkedInsurance
              ? String(coveringLinkedInsurance.id)
              : undefined;

            const { price, notCovered } = resolveBillingUnitPrice(
              basePrice,
              costs,
              meta,
              defaultProviderId,
            );

            let selectedCoverageId: string | undefined = undefined;
            if (coveringLinkedInsurance) {
              const best = findBestMatchingCoverage(
                (coveringLinkedInsurance.insuranceProvider as any)?.coverages || [],
                departmentInfo?.department?.id || catalogDepartmentId,
                departmentInfo?.encounterType || undefined,
              );
              selectedCoverageId = best?.coverageId;
            }

            const newBillingItem: BillingItem = {
              id: addedLine.id,
              productId: item.id,
              source: "USER",
              isNewInEditMode: isEditingBill,
              name: catalogProduct?.name || item.name,
              quantity: addedLine.quantity || quantity,
              price,
              basePrice,
              insuranceCoverageCosts: costs,
              insuranceCoverageMeta: meta,
              insuranceNotCovered: defaultVisitInsuranceId ? notCovered : false,
              type: "product",
              visitDepartmentId: newProduct?.id || catalogDepartmentId,
              rootVisitDepartmentId: newProduct?.id || catalogDepartmentId,
              departmentId: departmentInfo?.department?.id,
              departmentName: departmentInfo?.department?.name || "General",
              departmentStatus: departmentInfo?.status,
              encounterType: departmentInfo?.encounterType,
              paymentStatus: "pending",
              exempted: false,
              exemptionType: "none",
              selectedInsuranceId: defaultVisitInsuranceId,
              selectedCoverageId,
              processorId: processorId || undefined,
              processorName: newProcessorName || undefined,
              doneBy: {
                name: doctor?.firstName || "Doctor",
                title: "",
              },
            };

            setBillingData((prev) => {
              if (!prev) return prev;
              return {
                ...prev,
                items: [...prev.items, newBillingItem],
                updatedAt: new Date().toISOString(),
              };
            });
            await refetchVisit();
          }
        } else {
          // Fallback to refetch if response data is incomplete
          await refetchVisit();
        }
        setShowAddProductModal(false);
        const catalogPrice = Number(item.clinicPrice ?? item.privateRhicPrice ?? 0);
        const hasLinkedInsurances = (visit.linkedInsurances || []).length > 0;
        const rawCoverages = (item as any)?.insuranceCoverages || [];
        const { costs, meta } = buildProductCoverageMaps(rawCoverages);
        const activeLinkedInsurances = (visit.linkedInsurances || []).filter(isInsuranceActive);
        const coveringLinkedInsurance = activeLinkedInsurances.find((ins) => {
          const providerId = String(ins?.insuranceProvider?.id ?? "");
          return Boolean(meta[providerId]?.covered && Number(costs[providerId]) > 0);
        });

        if (hasLinkedInsurances && !coveringLinkedInsurance) {
          toast.warn(`"${item.name}" is not covered (pays 0 RWF) by the patient's insurance. Added as Private (${catalogPrice.toLocaleString()} RWF).`);
        } else if (catalogPrice === 0) {
          toast.warn(`"${item.name}" has no price set — it will bill at 0. Set a catalog price first.`);
        } else {
          toast.success("Product added successfully");
        }
      } else {
        const errorMsg =
          response?.messages?.[0]?.text || "Failed to add product";
        toast.error(errorMsg);
      }
    } catch (err) {
      console.error("Failed to add product to visit:", err);
      toast.error("Failed to add product. Please try again.");
    } finally {
      setAddingBillingItem(false);
    }
  };

  return {
    dischargeConfirmOpen,
    setDischargeConfirmOpen,
    postBillingActionOpen,
    setPostBillingActionOpen,
    requestDischarge,
    handleDischargeVisit,
    handleDownloadInvoice,
    handleChangeProfile,
    handlePreviewBilling,
    handleGenerateBill,
    handlePrintBillingInvoice,
    handleAddInsuranceToVisit,
    handleRemoveInsuranceFromVisit,
    handleAddProduct,
  };
}
